
package processing;

/**
 * Stores the results of a FASTQ read-end quality analysis.
 *
 * <p>This class is part of the SeqSpectre quality control tool.
 * It contains the general information about an analysed read
 * and the calculated quality statistics for both read ends.
 *
 * <p>Results are generated by AnalyseReadQuality and can
 * subsequently be used by other components, such as the
 * reporting and output generation modules.
 *
 * <p>Each read end is represented by an EndQuality object.
 * Both ends are stored separately, allowing independent
 * reporting and comparison of sequencing quality.
 *
 * <p>This class is immutable: all fields are final and
 * values are accessed through getter methods.
 *
 * @see AnalyseReadQuality
 */
public final class QualityResult {

    // Percentage of each read end selected for quality analysis.
    private final double percentage;

    // Total number of nucleotides in the original sequencing read.
    private final int readLength;

    // Number of bases analysed at each end after rounding upwards.
    private final int basesPerEnd;

    // Quality statistics calculated for the beginning of the read.
    private final EndQuality start;

    // Quality statistics calculated for the end of the read.
    private final EndQuality end;

    /**
     * Creates a result containing the quality statistics of a read.
     *
     * <p>The constructor stores the original analysis settings
     * and the independently calculated results for both ends.
     *
     * @param percentage percentage of each read end analysed
     * @param readLength total length of the original read
     * @param basesPerEnd number of selected bases at each end
     * @param start calculated statistics for the start region
     * @param end calculated statistics for the end region
     */
    public QualityResult(
            double percentage,
            int readLength,
            int basesPerEnd,
            EndQuality start,
            EndQuality end) {

        this.percentage = percentage;
        this.readLength = readLength;
        this.basesPerEnd = basesPerEnd;
        this.start = start;
        this.end = end;
    }

    /**
     * Returns the percentage used for the analysis.
     *
     * <p>The same percentage is applied independently
     * to both ends of the sequencing read.
     *
     * @return selected percentage per read end
     */
    public double getPercentage() {
        return percentage;
    }

    /**
     * Returns the total length of the original sequencing read.
     *
     * @return total number of nucleotides in the read
     */
    public int getReadLength() {
        return readLength;
    }

    /**
     * Returns the number of bases analysed at each read end.
     *
     * <p>This value is calculated by applying the selected
     * percentage to the read length and rounding upwards.
     *
     * @return number of analysed bases per read end
     */
    public int getBasesPerEnd() {
        return basesPerEnd;
    }

    /**
     * Returns the quality statistics for the beginning of the read.
     *
     * @return EndQuality containing the start-region statistics
     */
    public EndQuality getStart() {
        return start;
    }

    /**
     * Returns the quality statistics for the end of the read.
     *
     * @return EndQuality containing the end-region statistics
     */
    public EndQuality getEnd() {
        return end;
    }

    /**
     * Stores the quality statistics calculated for one read end.
     *
     * <p>An EndQuality object represents either the beginning
     * or the end of a sequencing read.
     *
     * <p>The following measurements are available:
     * <ul>
     *   <li>Mean Phred quality score.</li>
     *   <li>Median Phred quality score.</li>
     *   <li>Minimum Phred quality score.</li>
     *   <li>Percentage of bases meeting Q20.</li>
     *   <li>Percentage of bases meeting Q30.</li>
     *   <li>Mean sequencing error probability.</li>
     *   <li>Quality classification.</li>
     * </ul>
     *
     * <p>This nested class is immutable and provides
     * getter methods for use by reporting components.
     */
    public static final class EndQuality {

        // Arithmetic mean of all selected Phred quality scores.
        private final double meanQuality;

        // Median Phred score, representing the middle of the distribution.
        private final double medianQuality;

        // Lowest Phred quality score found in the selected region.
        private final int minimumQuality;

        // Percentage of selected bases with Phred Q20 or higher.
        private final double percentageQ20;

        // Percentage of selected bases with Phred Q30 or higher.
        private final double percentageQ30;

        // Mean estimated sequencing error probability per base.
        private final double meanErrorProbability;

        // Quality category assigned using SeqSpectre thresholds.
        private final String classification;

        /**
         * Creates an object containing quality statistics for one read end.
         *
         * <p>All values are calculated by AnalyseReadQuality
         * before being passed to this constructor.
         *
         * @param meanQuality arithmetic mean Phred score
         * @param medianQuality median Phred score
         * @param minimumQuality lowest Phred score
         * @param percentageQ20 percentage of bases with Q20 or higher
         * @param percentageQ30 percentage of bases with Q30 or higher
         * @param meanErrorProbability mean estimated error probability
         * @param classification GOOD, MODERATE or POOR
         */
        public EndQuality(
                double meanQuality,
                double medianQuality,
                int minimumQuality,
                double percentageQ20,
                double percentageQ30,
                double meanErrorProbability,
                String classification) {

            this.meanQuality = meanQuality;
            this.medianQuality = medianQuality;
            this.minimumQuality = minimumQuality;
            this.percentageQ20 = percentageQ20;
            this.percentageQ30 = percentageQ30;
            this.meanErrorProbability = meanErrorProbability;
            this.classification = classification;
        }

        /**
         * Returns the arithmetic mean of the selected Phred scores.
         *
         * <p>The mean is calculated by dividing the sum of
         * all selected Phred scores by the number of bases.
         *
         * @return mean Phred quality score
         */
        public double getMeanQuality() {
            return meanQuality;
        }

        /**
         * Returns the median of the selected Phred scores.
         *
         * <p>The median represents the middle value of the
         * sorted quality score distribution. For an even number
         * of bases, the two middle scores are averaged.
         *
         * @return median Phred quality score
         */
        public double getMedianQuality() {
            return medianQuality;
        }

        /**
         * Returns the lowest Phred score in the selected region.
         *
         * <p>This value identifies the lowest-quality nucleotide
         * and can help detect individual poor-quality bases.
         *
         * @return minimum Phred quality score
         */
        public int getMinimumQuality() {
            return minimumQuality;
        }

        /**
         * Returns the percentage of bases with Q20 or higher.
         *
         * <p>Q20 corresponds to an estimated sequencing
         * error probability of 1%.
         *
         * @return percentage of bases meeting the Q20 threshold
         */
        public double getPercentageQ20() {
            return percentageQ20;
        }

        /**
         * Returns the percentage of bases with Q30 or higher.
         *
         * <p>Q30 corresponds to an estimated sequencing
         * error probability of 0.1%.
         *
         * @return percentage of bases meeting the Q30 threshold
         */
        public double getPercentageQ30() {
            return percentageQ30;
        }

        /**
         * Returns the mean estimated sequencing error probability.
         *
         * <p>Each Phred score is converted to an error probability
         * using P(error) = 10^(-Q / 10).
         *
         * <p>The resulting probabilities are averaged across
         * all selected bases.
         *
         * <p>This value is a probability between 0 and 1,
         * not a percentage or a Phred score.
         *
         * @return mean estimated sequencing error probability
         */
        public double getMeanErrorProbability() {
            return meanErrorProbability;
        }

        /**
         * Returns the SeqSpectre quality classification.
         *
         * <p>Possible classifications:
         * <ul>
         *   <li>GOOD: at least 90% of bases have Q30 or higher.</li>
         *   <li>MODERATE: at least 90% have Q20 or higher,
         *       but fewer than 90% have Q30 or higher.</li>
         *   <li>POOR: fewer than 90% have Q20 or higher.</li>
         * </ul>
         *
         * @return quality classification as a String
         */
        public String getClassification() {
            return classification;
        }
    }
}
